import heapq
import sys

def min_partition_sum(n, c, a):
    # Initialize the dp array where dp[i] represents the minimum sum of values
    # for partitioning the subarray a[0:i+1]
    dp = [float('inf')] * n
    prefix_sum = [0] * (n + 1)

    # Calculate prefix sums for the array
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + a[i]

    # Function to calculate the sum of the k smallest elements in a subarray
    def sum_of_k_smallest(start, end, k):
        subarray = a[start:end]
        if len(subarray) <= k:
            return sum(subarray)
        heapq.heapify(subarray)
        smallest_sum = 0
        for _ in range(len(subarray) - k):
            smallest_sum += heapq.heappop(subarray)
        return sum(subarray)

    # Calculate the minimum sum of values for each partition
    for i in range(n):
        for j in range(i + 1):
            k = (i - j + 1) // c
            subarray_value = sum_of_k_smallest(j, i + 1, k)
            if j == 0:
                dp[i] = min(dp[i], subarray_value)
            else:
                dp[i] = min(dp[i], dp[j - 1] + subarray_value)

    return dp[n - 1]

def main():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    c = int(data[1])
    a = list(map(int, data[2:2 + n]))
    result = min_partition_sum(n, c, a)
    print(result)

if __name__ == "__main__":
    main()
